!function(n){function p(p){for(var t,e,o=p[0],s=p[1],c=p[2],m=0,g=[];m<o.length;m++)e=o[m],Object.prototype.hasOwnProperty.call(a,e)&&a[e]&&g.push(a[e][0]),a[e]=0;for(t in s)Object.prototype.hasOwnProperty.call(s,t)&&(n[t]=s[t]);for(u&&u(p);g.length;)g.shift()();return i.push.apply(i,c||[]),r()}function r(){for(var n,p=0;p<i.length;p++){for(var r,e=i[p],o=!0,s=1;s<e.length;s++)r=e[s],0!==a[r]&&(o=!1);o&&(i.splice(p--,1),n=t(t.s=e[0]))}return n}function t(p){if(e[p])return e[p].exports;var r=e[p]={i:p,l:!1,exports:{}};return n[p].call(r.exports,r,r.exports,t),r.l=!0,r.exports}var e={},a={12:0},i=[];t.m=n,t.c=e,t.d=function(n,p,r){t.o(n,p)||Object.defineProperty(n,p,{enumerable:!0,get:r})},t.r=function(n){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(n,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(n,"__esModule",{value:!0})},t.t=function(n,p){if(1&p&&(n=t(n)),8&p)return n;if(4&p&&"object"==typeof n&&n&&n.__esModule)return n;var r=Object.create(null);if(t.r(r),Object.defineProperty(r,"default",{enumerable:!0,value:n}),2&p&&"string"!=typeof n)for(var e in n)t.d(r,e,function(p){return n[p]}.bind(null,e));return r},t.n=function(n){var p=n&&n.__esModule?function(){return n.default}:function(){return n};return t.d(p,"a",p),p},t.o=function(n,p){return Object.prototype.hasOwnProperty.call(n,p)},t.p="";var o=window.webpackJsonp=window.webpackJsonp||[],s=o.push.bind(o);o.push=p,o=o.slice();for(var c=0;c<o.length;c++)p(o[c]);var u=s;i.push([85,0]),r()}({85:function(n,p,r){"use strict";r.r(p);var t=r(0);Object(t.a)("us","army",r(86),r(1))},86:function(n){n.exports=JSON.parse('{"category":[{"name":"美国","link":"us_shortcut"},{"name":"陆战武器","link":"us_army"},{"name":"火炮","link":"us_army#us_army_cannon"}],"model":"美军小口径反坦克炮","description":"<h6>综述：</h6><p>M3A1式37毫米炮和M1式57毫米炮是美军在二战时装备的两种小口径反坦克炮。</p><p>其中37毫米反坦克炮是美国在二战初期参考德国Pak35/36型37毫米反坦克炮所设计，开始定型为M3式，不久为该炮加上炮口制退器后改称为M3A1式（后发现制退器对这款小口径火炮作用不大又取消了）。1941年，这种37毫米反坦克炮产量开始增加，并配备给美军步兵使用，用来替代步兵用的12.7mm机枪，当时，每个美军步兵营都会配备一个装备3门小口径反坦克炮的反坦克排。每一个步兵团还会配属一个装备9门炮的反坦克连。37毫米反坦克炮第一次参战是在1941年12月的菲律宾战役。尽管随后这种37毫米炮已难以对付欧洲战场上不断增强的装甲战车，但在太平洋战场对日军的坦克仍然具有杀伤威力，因此该炮生产一直保持至二战结束，到1945年共生产了不少于18700门。</p><p>而M1式57毫米反坦克炮的原型是英军装备的6磅反坦克炮，这种炮装备美军时已是二战中后期，因此作为专用反坦克武器已经落后，但在欧洲作场上，57毫米反坦克炮的射击准确性在对付德军的坚固工事和机枪阵地时，却有极好的打击效果。而在城市巷战中，该炮也能用穿甲弹击穿敌方坦克装甲的薄弱部分造成坦克的损毁或坦克手的伤亡。但57毫米反坦克炮由于重量过大，在战场上转移阵地时会有一定困难，在诺曼底战场与阿登反击战时虽有一定战绩，但战力却难以与自行火炮相抗衡。</p>","part1title":"系列型号","part1description":"","part1content":[{"image":"imgs/us/army/us_army_cannonSAT_10.jpg","description":"<h6>M3A1式37mm反坦克炮</h6><p></p><p>基本技术数据：</p><p>火炮口径：37毫米；</p><p>火炮长度：1.979米；</p><p>火炮重量：410.4公斤（行军状态）；</p><p>方向射界：60度；</p><p>高低射角：-10度～15度；</p><p>炮口初速：885米/每秒；</p><p>有效射程：457米；</p><p>炮弹重量：0.86公斤；</p><p>破甲厚度：25毫米（1000米距离内）。</p>","caption":""},{"image":"imgs/us/army/us_army_cannonSAT_11.jpg","description":"<h6>M1式57mm反坦克炮</h6><p></p><p>基本技术数据：</p><p>火炮口径：57毫米；</p><p>炮管长度：2.54米；</p><p>火炮重量：1140公斤；</p><p>方向射界：90度；</p><p>高低射角：-5度～15度；</p><p>炮口初速：1219米/每秒；</p><p>有效射程：1510米；</p><p>破甲厚度：142毫米（1000米距离内）。</p>","caption":""}],"part2title":"战场上的美军小口径反坦克炮","part2description":"","part2content":[{"image":"imgs/us/army/us_army_cannonSAT_20.jpg","description":"二战初期，一名美军教官正向几名步兵介绍M3A1式37毫米反坦克炮的结构与使用方法。","caption":""},{"image":"imgs/us/army/us_army_cannonSAT_21.jpg","description":"二战初期，在火炮训练场上的一个美军步兵炮班正在进行M3式37毫米反坦克炮的射击训练。","caption":""},{"image":"imgs/us/army/us_army_cannonSAT_22.jpg","description":"1943年2月，北非战场，隶属美国第1装甲师装甲分队的一辆M3半履带装甲车牵引着一门M3式37毫米反坦克炮行进在沙路上。为了更好地融入沙漠背景，美军的装甲车用泥土作了临时伪装。","caption":""},{"image":"imgs/us/army/us_army_cannonSAT_23.jpg","description":"1944年，太平洋战场的一处岛屿上，美军一个步兵炮班的炮兵们正合力拖着一门M3式37毫米反坦克炮转移阵地。图中的树木已被炮火炸得七零八落，可知此处曾经历过激烈战斗。","caption":""},{"image":"imgs/us/army/us_army_cannonSAT_24.jpg","description":"1944年，太平洋战场的一处岛屿上，美军一门正在战斗中的M3式37毫米反坦克炮。在太平洋群岛争夺战中，用这种小口径火炮对付日军的碉堡与地下工事还是很有效的。","caption":""},{"image":"imgs/us/army/us_army_cannonSAT_25.jpg","description":"1943年7月4日，摩洛哥，美军第34师的M3半履带车拖着新的M1A3式57毫米反坦克炮参与在利奥泰港举行的阅兵仪式。在北非战场上，美军步兵在突尼斯战役中还在使用37毫米反坦克炮，直到在意大利西西里岛登陆作战前才开始接收新的57毫米反坦克炮。","caption":""},{"image":"imgs/us/army/us_army_cannonSAT_26.jpg","description":"1944年10月15日，在德国亚琛的激烈战斗中，美军反坦克连的一辆M2A1半履带装甲车拖着一门M1A3式57毫米反坦克炮向前行进。作为西线战场上第一个遭到盟军攻击的德国城市，亚琛的防御工事尤为坚固，美军攻入城后与德军展开了巷战。作为英国6磅反坦克炮复制品的这型57mm反坦克炮，在巷战攻坚中发挥了不少作用。","caption":""},{"image":"imgs/us/army/us_army_cannonSAT_27.jpg","description":"1945年3月，西线德国战场，正在一处城市街道上与德军作战的美军第29师一门M1式57毫米反坦克炮。","caption":""},{"image":"imgs/us/army/us_army_cannonSAT_28.jpg","description":"1944年11月，西线战场，据守在野外阵地上的美军一门M1式57毫米反坦克炮和一挺重机枪。在野战中，这些武器主要用于对付德军的步兵与轻、中型装甲战车，而难以与德军西线装甲师的重型坦克相抗衡。","caption":""},{"image":"imgs/us/army/us_army_cannonSAT_29.jpg","description":"二战后期西线战场，利用战斗间隙休息的美军一门M1式57毫米反坦克炮的炮班士兵，连续战斗确实让这些炮兵们感到十分疲倦。","caption":""},{"image":"imgs/us/army/us_army_cannonSAT_30.jpg","description":"1944年冬季，西线战场，美军炮兵正在努力将一门M1式57毫米反坦克炮推出泥泞，让半履带装甲车顺利牵引。美军普遍认为57毫米反坦克炮重量太大，不利于迅速转移阵地。","caption":""}]}')}});